ORDER BY RAND() LIMIT #{limit}

SELECT p.id, p.category_id, p.tag_id, p.name, p.sub_title, p.brand, p.title, p.image, p.sales_mode, p.listing_status, p.sales_price, p.market_price, p.product_code, p.stock, p.specs, p.create_time, p.update_time FROM products p JOIN categories c ON p.category_id = c.id LEFT JOIN categories parent ON c.parent_id = parent.id WHERE p.listing_status = 1 AND (c.recommend = 1 OR parent.recommend = 1)
AND p.id NOT IN
#{id}
ORDER BY RAND() LIMIT #{limit}

mapper.sql:
FROM products p
WHERE p.listing_status = 1

    AND p.category_id IN (
        SELECT id FROM categories WHERE id = #{categoryId} OR parent_id = #{categoryId}
    )


    AND (p.name LIKE CONCAT('%', #{keyword}, '%')
         OR p.sub_title LIKE CONCAT('%', #{keyword}, '%')
         OR p.brand LIKE CONCAT('%', #{keyword}, '%'))


    AND p.brand = #{brand}


    AND p.sales_price >= #{minPrice}


    AND p.sales_price <= #{maxPrice}

mapper.update:
UPDATE products
category_id = #{categoryId}, tag_id = #{tagId}, name = #{name}, sub_title = #{subTitle}, brand = #{brand}, title = #{title}, image = #{image}, body = #{body}, sales_mode = #{salesMode}, listing_status = #{listingStatus}, sales_price = #{salesPrice}, market_price = #{marketPrice}, cost_price = #{costPrice}, product_code = #{productCode}, stock = #{stock}, specs = #{specs}, sku_type = #{skuType}, sku_specs = #{skuSpecs}, update_time = #{updateTime},
WHERE id = #{id}
